 let pins=read(r.join("build-pins-v2.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let cpins=read(r.join("capture-pins.json"));for(p,h)in cpins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}
 let b=read(r.join("backings.json"));let mut seen=BTreeSet::new();let mut hashes=BTreeMap::<String,String>::new();for b in b.as_array().unwrap(){let prefix=b["prefix"].as_str().unwrap();let path=b["path"].as_str().unwrap();let meta=fs::metadata(path).unwrap();use std::os::unix::fs::MetadataExt;assert_eq!(meta.dev(),b["dev"].as_u64().unwrap());assert_eq!(meta.ino(),b["inode"].as_u64().unwrap());assert!(seen.insert((meta.dev(),meta.ino())));let h=hash(path);assert_eq!(h,b["sha256"].as_str().unwrap());if let Some(prior)=hashes.insert(prefix.into(),h.clone()){assert_eq!(prior,h);}}
 assert_eq!(seen.len(),6);assert_ne!(hashes["sdk"],hashes["ref"]);assert_eq!(hashes["ref"],"bcc8e0775bb5bc6c09ad86b1987ca45eebac62617340911266c84aa601fa05b1");assert_eq!(hashes["sdk"],hash(r.join("build-run-v2/candidate-sdk")));
 let seed="/home/ubuntu/src/zopro-perf-work/static-query-profile206/proof-sha256-after-profile.json";assert_eq!(hash(seed),"8e40735a1253e777437b8a1d06ca29a61642129fea8fcf5b68d7cebe8fbd35ee");let mut ledger:BTreeSet<String>=serde_json::from_value(read(seed)).unwrap();assert_eq!(ledger.len(),58915);let jobs=read(r.join("jobs.json"));let rows=read(r.join("main-rows.json"));let result=read(r.join("result.json"));let mut measured=BTreeMap::<String,(f64,f64,f64)>::new();let mut receipts=0;let mut calls=0;
