 let out=fs::read_to_string(r.join(format!("{}-run/{name}/stdout.log",if smoke{"smoke"}else{"main"}))).unwrap();let values=out.lines().filter_map(|l|l.strip_prefix("SAMPLE ")).map(|l|serde_json::from_str::<Value>(l).unwrap()["ms"].as_f64().unwrap()).collect::<Vec<_>>();let sums=out.lines().filter_map(|l|l.strip_prefix("SUMMARY ")).map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();assert_eq!(sums.len(),1);let s=&sums[0];let rounds=j["rounds"].as_u64().unwrap()as usize;assert_eq!(values.len(),rounds);assert_eq!(s["priming"],3);assert_eq!(s["generated_fast_parses"],rounds);assert_eq!(s["generated_timed_key_scans"],0);assert_eq!(s["generated_timed_fixed_scans"],0);assert_eq!(s["placement_before"],s["placement_after"]);for(i,row)in s["placement_before"]["worker_rows"].as_array().unwrap().iter().enumerate(){assert_eq!(row["allowed"],json!([i]));}
 if j["arm"]=="ON"{let n=if j["case"]["shape"]=="1x2"{1}else{2};let mut routes=[0;4];routes[n]=rounds;assert_eq!(s["boolean_routes"],json!(routes));assert_eq!(s["boolean_positions"],if n==1{1753}else{3166});assert!(s["boolean_workspace"].as_u64().unwrap()>0);}else if j["arm"]=="OFF"{assert_eq!(s["boolean_routes"],json!([0,0,0,0]));assert_eq!(s["boolean_positions"],0);}
