 for c in result["comparisons"].as_array().unwrap(){let shape=c["shape"].as_str().unwrap();let w=c["workers"].as_u64().unwrap();let get=|arm:&str,b:usize|measured[&format!("main-{shape}-w{w}-{arm}-b{b}")];let ratios=(0..3).map(|b|get("ON",b).0/get("REF",b).0).collect::<Vec<_>>();let ratio=median(ratios.clone());let wins=ratios.iter().filter(|&&v|v<1.).count();let cpu=median((0..3).map(|b|get("ON",b).1/get("REF",b).1).collect());let peak=|arm:&str|(0..3).map(|b|get(arm,b).2).fold(0.,f64::max);let guard=ratio<=1.02&&cpu<=1.02&&peak("ON")<=(peak("REF")*1.1).max(peak("REF")+8.);let gain=shape!="1x2"||w!=32||ratio<1.&&wins>=2;advance&=guard&&gain;close(ratio,c["paired_median"].as_f64().unwrap());close(cpu,c["paired_cpu_median"].as_f64().unwrap());assert_eq!(c["wins"],wins);assert_eq!(c["guards"],guard);assert_eq!(c["gain_selection"],gain);
 }
 assert_eq!(result["advance_to_qualification"],advance);assert_eq!(result["adopted"],false);let out=json!({"pass":true,"original_sources_unchanged":179,"private_unchanged":originals,"private_modified":4,"new_modules":1,"field_source_files":fields,"receipts":receipts,"stream_hashes":receipts*2,"SDK_calls":calls,"fresh_verified_exports":33,"canonical_count":ledger.len(),"canonical_sha256":hash(r.join("proof-sha256-after-main.json")),"advance_to_qualification":advance,"adopted":false,"sdk_sha256":hashes["sdk"],"backings":6});fs::write(r.join("review.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("{out}");
